pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, address(this).balance + 1 ether);

        Receiver r = new Receiver();

        vm.deal(address(c), amount);

        uint256 before = c.depositsCount();

        c.sendMoney(address(r), amount);

        assertTrue(c.depositsCount() == before);
    }
}

contract Receiver {
    receive() external payable {}
    fallback() external payable {}
}
